Design:
{
 "context": "payments",
 "base_package": "com.bank.payments",
 "entities": [
  {
   "name": "Order",
   "table": "orders",
   "legacy_table": "ORDENES",
   "key": [
    "orderNumber",
    "companyId"
   ],
   "fields": [
    {
     "name": "orderNumber",
     "type": "integer(32,signed)",
     "column": "order_number",
     "legacy": "ORD_NUMERO"
    },
    {
     "name": "companyId",
     "type": "integer(32,signed)",
     "column": "company_id",
     "legacy": "ORD_EMPRESA"
    },
    {
     "name": "status",
     "type": "text(fixed,1,iso8859-1)",
     "column": "status",
     "legacy": "ORD_ESTADO"
    },
    {
     "name": "value",
     "type": "decimal(11,2,signed)",
     "column": "order_value",
     "legacy": "ORD_VALOR"
    },
    {
     "name": "movementNumber",
     "type": "integer(64,signed)",
     "column": "movement_number",
     "legacy": "ORD_MOVIM"
    },
    {
     "name": "commission",
     "type": "decimal(5,2,signed)",
     "column": "commission",
     "legacy": "ORD_COMIS"
    }
   ]
  },
  {
   "name": "Account",
   "table": "accounts",
   "legacy_table": "CUENTAS",
   "key": [
    "accountNumber"
   ],
   "fields": [
    {
     "name": "accountNumber",
     "type": "integer(64,signed)",
     "column": "account_number",
     "legacy": "CTA_NUMERO"
    },
    {
     "name": "accountType",
     "type": "text(fixed,3,iso8859-1)",
     "column": "account_type",
     "legacy": "CTA_TIPO"
    },
    {
     "name": "balance",
     "type": "decimal(13,2,signed)",
     "column": "balance",
     "legacy": "CTA_SALDO"
    },
    {
     "name": "status",
     "type": "text(fixed,1,iso8859-1)",
     "column": "status",
     "legacy": "CTA_ESTADO"
    }
   ]
  }
 ],
 "ports": [
  {
   "name": "OrderRepository",
   "entity": "Order",
   "legacy_program": null,
   "methods": [
    {
     "name": "findByKey",
     "description": "Reads an order by order number and company, locking it for update (READ ORDENES ... UPDATE). Empty when not found.",
     "inputs": [
      {
       "name": "orderNumber",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "ORD_NUMERO"
      },
      {
       "name": "companyId",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "ORD_EMPRESA"
      }
     ],
     "returns": "Order",
     "legacy_output": null
    },
    {
     "name": "markPaid",
     "description": "Rewrites the order as paid ('G') with its movement number and the commission charged.",
     "inputs": [
      {
       "name": "orderNumber",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "ORD_NUMERO"
      },
      {
       "name": "companyId",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "ORD_EMPRESA"
      },
      {
       "name": "movementNumber",
       "type": "integer(64,signed)",
       "column": null,
       "legacy": "ORD_MOVIM"
      },
      {
       "name": "commission",
       "type": "decimal(5,2,signed)",
       "column": null,
       "legacy": "ORD_COMIS"
      }
     ],
     "returns": null,
     "legacy_output": null
    }
   ]
  },
  {
   "name": "AccountRepository",
   "entity": "Account",
   "legacy_program": null,
   "methods": [
    {
     "name": "findByNumber",
     "description": "Reads an account by number, locking it for update (READ CUENTAS ... UPDATE). Empty when not found.",
     "inputs": [
      {
       "name": "accountNumber",
       "type": "integer(64,signed)",
       "column": null,
       "legacy": "CTA_NUMERO"
      }
     ],
     "returns": "Account",
     "legacy_output": null
    },
    {
     "name": "updateBalance",
     "description": "Rewrites the account with its new balance.",
     "inputs": [
      {
       "name": "accountNumber",
       "type": "integer(64,signed)",
       "column": null,
       "legacy": "CTA_NUMERO"
      },
      {
       "name": "balance",
       "type": "decimal(13,2,signed)",
       "column": null,
       "legacy": "CTA_SALDO"
      }
     ],
     "returns": null,
     "legacy_output": null
    }
   ]
  },
  {
   "name": "MovementGateway",
   "entity": null,
   "legacy_program": "PAGOMOV",
   "methods": [
    {
     "name": "registerMovement",
     "description": "Registers the payment movement for an order (LINK PAGOMOV) and returns the movement number.",
     "inputs": [
      {
       "name": "orderNumber",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "MOV_ORDEN"
      }
     ],
     "returns": "long",
     "legacy_output": "MOV_NUMERO"
    }
   ]
  }
 ],
 "use_cases": [
  {
   "name": "DebitAccount",
   "description": "Debits a customer account (legacy PAGODEB). Rejects with a response code when the account does not exist, the type differs, the account is inactive or the balance is insufficient; otherwise subtracts the amount and persists the new balance.",
   "rules": [
    "RULE-001",
    "RULE-002",
    "RULE-003",
    "RULE-004",
    "RULE-005"
   ],
   "inputs": [
    {
     "name": "accountNumber",
     "type": "integer(64,signed)",
     "column": null,
     "legacy": "DEB_CUENTA"
    },
    {
     "name": "accountType",
     "type": "text(fixed,3,iso8859-1)",
     "column": null,
     "legacy": "DEB_TIPO"
    },
    {
     "name": "amount",
     "type": "decimal(13,2,signed)",
     "column": null,
     "legacy": "DEB_MONTO"
    }
   ],
   "outputs": [
    {
     "name": "responseCode",
     "type": "text(fixed,2,iso8859-1)",
     "column": null,
     "legacy": "DEB_RESP"
    },
    {
     "name": "newBalance",
     "type": "decimal(13,2,signed)",
     "column": null,
     "legacy": "CTA_SALDO"
    }
   ],
   "errors": [
    {
     "code": "ACCOUNT_NOT_FOUND",
     "legacy_code": "30",
     "message": "Account does not exist"
    },
    {
     "code": "ACCOUNT_TYPE_MISMATCH",
     "legacy_code": "40",
     "message": "Account type does not match the requested type"
    },
    {
     "code": "ACCOUNT_INACTIVE",
     "legacy_code": "10",
     "message": "Account is not active"
    },
    {
     "code": "INSUFFICIENT_FUNDS",
     "legacy_code": "20",
     "message": "Insufficient balance"
    }
   ],
   "ports": [
    "AccountRepository"
   ],
   "http_method": "POST",
   "path": "/payments/accounts/debits",
   "legacy_program": "PAGODEB",
   "unit_of_work": null,
   "legacy_message": "DEB_RESP"
  },
  {
   "name": "PayOrder",
   "description": "Pays a pending order (legacy PAGOORD): validates the entry, reads the order, checks the amount, calculates the commission, debits the account, registers the movement and marks the order as paid, all in one transaction.",
   "rules": [
    "RULE-007",
    "RULE-008",
    "RULE-009",
    "RULE-010",
    "RULE-011",
    "RULE-012",
    "RULE-013",
    "RULE-014",
    "RULE-015"
   ],
   "inputs": [
    {
     "name": "orderNumber",
     "type": "text(fixed,7,iso8859-1)",
     "column": null,
     "legacy": "ORDEN"
    },
    {
     "name": "companyId",
     "type": "text(fixed,5,iso8859-1)",
     "column": null,
     "legacy": "EMPRESA"
    },
    {
     "name": "accountType",
     "type": "text(fixed,3,iso8859-1)",
     "column": null,
     "legacy": "TIPCTA"
    },
    {
     "name": "accountNumber",
     "type": "text(fixed,10,iso8859-1)",
     "column": null,
     "legacy": "CUENTA"
    },
    {
     "name": "amount",
     "type": "text(var,11,iso8859-1)",
     "column": null,
     "legacy": "VALOR"
    },
    {
     "name": "channel",
     "type": "text(fixed,3,iso8859-1)",
     "column": null,
     "legacy": "CANAL"
    },
    {
     "name": "approvalKey",
     "type": "text(fixed,6,iso8859-1)",
     "column": null,
     "legacy": "CLAVE"
    }
   ],
   "outputs": [
    {
     "name": "orderNumber",
     "type": "integer(32,signed)",
     "column": null,
     "legacy": "RORDEN"
    },
    {
     "name": "commission",
     "type": "decimal(5,2,signed)",
     "column": null,
     "legacy": "RCOMIS"
    },
    {
     "name": "movementNumber",
     "type": "integer(64,signed)",
     "column": null,
     "legacy": "RMOVIM"
    },
    {
     "name": "resultMessage",
     "type": "text(var,40,iso8859-1)",
     "column": null,
     "legacy": "RMENS"
    }
   ],
   "errors": [
    {
     "code": "INVALID_ORDER_NUMBER",
     "legacy_code": "-1",
     "message": "NUMERO DE ORDEN INVALIDO"
    },
    {
     "code": "ACCOUNT_TYPE_NOT_ALLOWED",
     "legacy_code": "-1",
     "message": "TIPO DE CUENTA NO PERMITIDO"
    },
    {
     "code": "CHANNEL_NOT_ALLOWED",
     "legacy_code": "-1",
     "message": "CANAL NO PERMITIDO"
    },
    {
     "code": "APPROVAL_KEY_REQUIRED",
     "legacy_code": "-1",
     "message": "CLAVE DE APROBACION REQUERIDA"
    },
    {
     "code": "ORDER_NOT_FOUND",
     "legacy_code": "-1",
     "message": "ORDEN NO EXISTE"
    },
    {
     "code": "ORDER_NOT_PENDING",
     "legacy_code": "-1",
     "message": "ORDEN NO ESTA PENDIENTE"
    },
    {
     "code": "AMOUNT_MISMATCH",
     "legacy_code": "-1",
     "message": "VALOR NO COINCIDE CON LA ORDEN"
    },
    {
     "code": "ACCOUNT_INACTIVE",
     "legacy_code": "10",
     "message": "CUENTA INACTIVA"
    },
    {
     "code": "INSUFFICIENT_FUNDS",
     "legacy_code": "20",
     "message": "SALDO INSUFICIENTE"
    },
    {
     "code": "INVALID_ACCOUNT",
     "legacy_code": "30/40",
     "message": "CUENTA NO VALIDA"
    }
   ],
   "ports": [
    "OrderRepository",
    "AccountRepository",
    "MovementGateway"
   ],
   "http_method": "POST",
   "path": "/payments/orders/payments",
   "legacy_program": "PAGOORD",
   "unit_of_work": {
    "begins_at": 37,
    "commits_at": 172,
    "savepoints": [],
    "rollbacks": []
   },
   "legacy_message": "MENSAJE"
  },
  {
   "name": "SelectMenuOption",
   "description": "Routes the option chosen on the payments main menu (legacy PAGOMNU): '1' goes to order payment, '9' ends the session, any other option is rejected.",
   "rules": [
    "RULE-006"
   ],
   "inputs": [
    {
     "name": "option",
     "type": "text(fixed,1,iso8859-1)",
     "column": null,
     "legacy": "OPCIONI"
    }
   ],
   "outputs": [
    {
     "name": "nextAction",
     "type": "text(var,20,iso8859-1)",
     "column": null,
     "legacy": "OPCIONI"
    },
    {
     "name": "message",
     "type": "text(var,78,iso8859-1)",
     "column": null,
     "legacy": "MENSAJEO"
    }
   ],
   "errors": [
    {
     "code": "INVALID_OPTION",
     "legacy_code": "OTHER",
     "message": "OPCION NO VALIDA"
    }
   ],
   "ports": [],
   "http_method": "POST",
   "path": "/payments/menu/options",
   "legacy_program": "PAGOMNU",
   "unit_of_work": null,
   "legacy_message": "MENSAJEO"
  }
 ],
 "decisions": [
  {
   "title": "Data moves to the target database (migration)",
   "context": "ORDENES and CUENTAS are VSAM KSDS files accessed through CICS; there is no relational schema or driver to keep.",
   "decision": "Both files become relational tables (orders, accounts) in the target database, with the legacy precision of every field.",
   "consequences": "The files need an initial load. Reads with UPDATE become row locks (SELECT ... FOR UPDATE) inside the transaction."
  },
  {
   "title": "One transaction for the whole payment",
   "context": "PAGOORD works inside a unit of work from begin at line 37 to the SYNCPOINT at line 172. It includes the account rewrite made by PAGODEB through LINK. All rejections happen before any write.",
   "decision": "PayOrder is transactional and covers the debit, the movement registration and the order rewrite. There are no savepoints or rollback points in the legacy, so none are declared. Any exception rolls the whole transaction back.",
   "consequences": "Debit and order update are atomic. If PAGOMOV or the order rewrite fails after the debit, the debit is undone, which the legacy did only implicitly."
  },
  {
   "title": "PAGODEB becomes an internal use case",
   "context": "PAGODEB has its source and works on CUENTAS, which migrates.",
   "decision": "Rules 001-005 are implemented in the DebitAccount use case. PayOrder calls it in-process in the same transaction and maps response codes 10, 20 and 30/40 to the messages of rule 014. It is also exposed over HTTP.",
   "consequences": "No LINK/commarea. The balance check keeps its legacy semantics: a balance equal to the amount is allowed."
  },
  {
   "title": "PAGOMOV stays behind a port",
   "context": "PAGOMOV is not among the inputs and is stubbed in the traces. Its non-zero status is not an output parameter.",
   "decision": "MovementGateway.registerMovement replaces the LINK and returns MOV_NUMERO. The adapter raises a failure on a non-zero status.",
   "consequences": "Replay uses the stub of the trace, and the call is checked with the argument MOV_ORDEN."
  },
  {
   "title": "Amount parsing follows the traces",
   "context": "Rule 012 says NUMVAL(VALORI)/100, but the traces send VALOR as '1500.00' and expect the order of 1500.00 to match.",
   "decision": "The amount is received as text. A value with an explicit decimal point is taken as written. A digits-only value is read with two implied decimals (/100). The comparison with the order value is exact.",
   "consequences": "A reviewer must confirm this at C3. If a digits-only value should be taken as written, the rule changes."
  },
  {
   "title": "Presentation and CICS plumbing are not translated",
   "context": "BMS maps, RECEIVE/SEND, RETURN TRANSID, XCTL, the commarea, PF3/ENTER keys and 'TECLA NO VALIDA' belong to the 3270 conversation.",
   "decision": "The use cases are stateless HTTP operations. Rejections are business errors with stable codes. The menu use case returns the next action instead of an XCTL.",
   "consequences": "CA-ULTIMA-ORDEN is not kept as session state, because it only fed the next screen."
  },
  {
   "title": "Rules exercised by each PAGOORD trace",
   "context": "The rule lists in the trace metadata do not match what each trace really exercises (for example orden_invalida lists RULE-001, which belongs to PAGODEB). The golden master is replayed from traces/PAGOORD.json over the tables ORDENES and CUENTAS.",
   "decision": "By legacy flow: pago_web_exitoso, pago_oficina_exento and pago_web_cuenta_ahorro exercise RULE-007 to RULE-009, RULE-011 to RULE-015 and the debit rules RULE-002 to RULE-005 (RULE-010 only for the office one). orden_invalida: RULE-007. tipo_cuenta_no_permitido: RULE-008. canal_no_permitido: RULE-009. oficina_sin_clave: RULE-010. orden_no_existe and orden_no_pendiente: RULE-011. valor_no_coincide: RULE-012. cuenta_inactiva: RULE-003 and RULE-014. saldo_insuficiente: RULE-004 and RULE-014. cuenta_no_existe: RULE-001 and RULE-014. tipo_no_coincide: RULE-002 and RULE-014. RULE-013 is exercised by every case that reaches the commission calculation.",
   "consequences": "RULE-006 (PAGOMNU) has no trace and is not covered by the replay."
  }
 ],
 "masks": [],
 "infrastructure": [],
 "data_strategy": "migration"
}

Use case: PayOrder

Rules:
[
 {
  "id": "RULE-007",
  "name": "Order number must be numeric and non-zero",
  "category": "validation",
  "priority": "P1",
  "statement": "When the order number ORDENI is not numeric or equals zeros, the message 'NUMERO DE ORDEN INVALIDO' is set in WS-MENSAJE and the HAY-ERROR flag is set.",
  "condition": "ORDENI NOT NUMERIC OR ORDENI = ZEROS",
  "action": "Set message 'NUMERO DE ORDEN INVALIDO' and flag the request as in error. No order is read and no debit is made.",
  "inputs": [
   {
    "name": "ORDENI",
    "type": "text(fixed,7,ebcdic)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "WS-MENSAJE",
    "type": "text(fixed,78,ebcdic)",
    "description": ""
   },
   {
    "name": "WS-ERROR",
    "type": "text(fixed,1,ebcdic)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Order number is zero\n Given the order number entered is 0000000\n When the user presses ENTER\n Then the message 'NUMERO DE ORDEN INVALIDO' is shown and the payment is not processed",
   "Scenario: Order number contains letters\n Given the order number entered is 12A4567\n When the user presses ENTER\n Then the message 'NUMERO DE ORDEN INVALIDO' is shown"
  ],
  "sources": [
   {
    "file": "cbl/PAGOORD.cbl",
    "line_start": 83,
    "line_end": 85
   }
  ]
 },
 {
  "id": "RULE-008",
  "name": "Allowed account types for order payment",
  "category": "validation",
  "priority": "P0",
  "statement": "Only account types CTE, AHO and VIR may be used to pay an order. Any other type is rejected with 'TIPO DE CUENTA NO PERMITIDO'.",
  "condition": "TIPCTAI NOT IN ('CTE','AHO','VIR')",
  "action": "Set message 'TIPO DE CUENTA NO PERMITIDO' and flag the request as in error.",
  "inputs": [
   {
    "name": "TIPCTAI",
    "type": "text(fixed,3,ebcdic)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "WS-MENSAJE",
    "type": "text(fixed,78,ebcdic)",
    "description": ""
   },
   {
    "name": "WS-ERROR",
    "type": "text(fixed,1,ebcdic)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Savings account accepted\n Given a valid order number and account type AHO\n When the request is validated\n Then the account type check passes",
   "Scenario: Unknown account type\n Given a valid order number and account type XYZ\n When the request is validated\n Then the message 'TIPO DE CUENTA NO PERMITIDO' is shown"
  ],
  "sources": [
   {
    "file": "cbl/PAGOORD.cbl",
    "line_start": 87,
    "line_end": 90
   }
  ]
 },
 {
  "id": "RULE-009",
  "name": "Allowed channels for order payment",
  "category": "validation",
  "priority": "P1",
  "statement": "The payment channel must be WEB or OFI. Any other channel is rejected with 'CANAL NO PERMITIDO'.",
  "condition": "CANALI NOT IN ('WEB','OFI')",
  "action": "Set message 'CANAL NO PERMITIDO' and flag the request as in error.",
  "inputs": [
   {
    "name": "CANALI",
    "type": "text(fixed,3,ebcdic)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "WS-MENSAJE",
    "type": "text(fixed,78,ebcdic)",
    "description": ""
   },
   {
    "name": "WS-ERROR",
    "type": "text(fixed,1,ebcdic)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Invalid channel\n Given a valid order number, account type CTE and channel ATM\n When the request is validated\n Then the message 'CANAL NO PERMITIDO' is shown",
   "Scenario: Valid channel\n Given channel WEB\n When the request is validated\n Then the channel check passes"
  ],
  "sources": [
   {
    "file": "cbl/PAGOORD.cbl",
    "line_start": 92,
    "line_end": 94
   }
  ]
 },
 {
  "id": "RULE-010",
  "name": "Office channel requires approval key",
  "category": "validation",
  "priority": "P1",
  "statement": "A payment through the office channel (OFI) must carry an approval key. If the key is blank the request is rejected with 'CLAVE DE APROBACION REQUERIDA'.",
  "condition": "CANALI = 'OFI' AND CLAVEI = SPACES",
  "action": "Set message 'CLAVE DE APROBACION REQUERIDA' and flag the request as in error.",
  "inputs": [
   {
    "name": "CANALI",
    "type": "text(fixed,3,ebcdic)",
    "description": ""
   },
   {
    "name": "CLAVEI",
    "type": "text(fixed,6,ebcdic)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "WS-MENSAJE",
    "type": "text(fixed,78,ebcdic)",
    "description": ""
   },
   {
    "name": "WS-ERROR",
    "type": "text(fixed,1,ebcdic)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: OFI without key\n Given channel OFI and a blank approval key\n When the request is validated\n Then the message 'CLAVE DE APROBACION REQUERIDA' is shown",
   "Scenario: WEB without key\n Given channel WEB and a blank approval key\n When the request is validated\n Then no error is raised for the key"
  ],
  "sources": [
   {
    "file": "cbl/PAGOORD.cbl",
    "line_start": 96,
    "line_end": 99
   }
  ]
 },
 {
  "id": "RULE-011",
  "name": "Order must exist and be pending",
  "category": "validation",
  "priority": "P0",
  "statement": "The order, identified by company and order number, must exist and be in pending status to be paid. Otherwise the payment is rejected with 'ORDEN NO EXISTE' or 'ORDEN NO ESTA PENDIENTE'.",
  "condition": "READ of ORDENES by (EMPRESAI, ORDENI) returns NOTFND, or the record is not ORD-PENDIENTE",
  "action": "Set 'ORDEN NO EXISTE' if not found, or 'ORDEN NO ESTA PENDIENTE' if the status is not pending, and flag the request as in error.",
  "inputs": [
   {
    "name": "ORDENI",
    "type": "text(fixed,7,ebcdic)",
    "description": ""
   },
   {
    "name": "EMPRESAI",
    "type": "text(fixed,5,ebcdic)",
    "description": ""
   },
   {
    "name": "ORD-ESTADO",
    "type": "text(fixed,1,ebcdic)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "WS-MENSAJE",
    "type": "text(fixed,78,ebcdic)",
    "description": ""
   },
   {
    "name": "WS-ERROR",
    "type": "text(fixed,1,ebcdic)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Order not found\n Given no order 1234567 exists for company 00010\n When payment is requested\n Then the message 'ORDEN NO EXISTE' is shown",
   "Scenario: Order already paid\n Given order 1234567 exists with a status other than pending\n When payment is requested\n Then the message 'ORDEN NO ESTA PENDIENTE' is shown"
