    /** In-memory fakes of the three ports, recording every call in order. */
    private static final class Fixture {
        final List<String> calls = new ArrayList<>();
        final List<Object[]> markPaidCalls = new ArrayList<>();
        final List<Object[]> updateBalanceCalls = new ArrayList<>();
        final List<Integer> movementCalls = new ArrayList<>();
        Order order = new Order(1234567, 10, PENDING, new BigDecimal("1000.00"), null, null);
        Account account = new Account(1234L, "CTE", new BigDecimal("5000.00"), ACTIVE);
        long movementNumber = 9000000001L;

        final OrderRepository orders = new OrderRepository() {
            @Override
            public Optional<Order> findByKey(Integer orderNumber, Integer companyId) {
                calls.add("order.find");
                if (order != null && order.orderNumber().equals(orderNumber)
                        && order.companyId().equals(companyId)) {
                    return Optional.of(order);
                }
                return Optional.empty();
            }

            @Override
            public void markPaid(Integer orderNumber, Integer companyId, Long movementNumber,
                                 BigDecimal commission) {
                calls.add("order.markPaid");
                markPaidCalls.add(new Object[] {orderNumber, companyId, movementNumber, commission});
            }
        };

        final AccountRepository accounts = new AccountRepository() {
            @Override
            public Optional<Account> findByNumber(Long accountNumber) {
                calls.add("account.find");
                if (account != null && account.accountNumber().equals(accountNumber)) {
                    return Optional.of(account);
                }
                return Optional.empty();
            }

            @Override
            public void updateBalance(Long accountNumber, BigDecimal balance) {
                calls.add("account.update");
                updateBalanceCalls.add(new Object[] {accountNumber, balance});
            }
        };

        final MovementGateway movements = new MovementGateway() {
            @Override
            public long registerMovement(Integer orderNumber) {
                calls.add("movement.register");
                movementCalls.add(orderNumber);
                return movementNumber;
            }
        };

        PayOrderService service() {
            return new PayOrderService(orders, accounts, movements);
        }

        void assertNoWrites() {
            assertThat(calls).doesNotContain("account.update", "movement.register", "order.markPaid");
            assertThat(updateBalanceCalls).isEmpty();
            assertThat(movementCalls).isEmpty();
            assertThat(markPaidCalls).isEmpty();
        }
    }

    private static PayOrderRequest request(String order, String company, String type, String account,
                                           String amount, String channel, String key) {
        return new PayOrderRequest(order, company, type, account, amount, channel, key);
    }

    private static PayOrderRequest validRequest() {
        return request("1234567", "00010", "CTE", "0000001234", "1000.00", "WEB", BLANK_KEY);
    }

    private static void assertRejected(Fixture fx, PayOrderRequest request, String code, String legacyCode,
                                       String message) {
        assertThatThrownBy(() -> fx.service().execute(request))
                .isInstanceOf(BusinessError.class)
                .satisfies(e -> {
                    BusinessError be = (BusinessError) e;
                    assertThat(be.code()).isEqualTo(code);
                    assertThat(be.legacyCode()).isEqualTo(legacyCode);
                    assertThat(be.getMessage()).isEqualTo(message);
                });
    }

    private static void assertLastBalance(Fixture fx, String expected) {
        assertThat(fx.updateBalanceCalls).hasSize(1);
        assertThat(fx.updateBalanceCalls.get(0)[0]).isEqualTo(1234L);
        assertThat((BigDecimal) fx.updateBalanceCalls.get(0)[1]).isEqualByComparingTo(new BigDecimal(expected));
    }

